// Find the 'clients' project from all projects
const projects = $input.first().json.result || [];
console.log(`Checking ${projects.length} projects for 'clients' project`);

let clientsProject = null;

for (const project of projects) {
  const projectName = project.name ? project.name.toString().toLowerCase() : '';

  if (projectName === 'clients') {
    clientsProject = project;
    console.log(`✅ Found clients project: "${project.name}" (ID: ${project.id})`);
    break;
  }
}

if (!clientsProject) {
  console.log('❌ Clients project not found');
  console.log('Available projects:', projects.map(p => p.name).join(', '));
  throw new Error('Clients project not found');
}

// Return the project details for the next node
return [{ json: { project_id: clientsProject.id, project_name: clientsProject.name } }];

// Process tasks from clients project and prepare for attachment fetching
const response = $input.first().json;
const tasks = response.result || [];
const projectData = $input.all()[0].json;

console.log(`Processing ${tasks.length} tasks from clients project (${projectData.project_name})`);

const clientTasks = [];

for (const task of tasks) {
  // Extract company name from task title (assuming title contains company name)
  const companyName = task.title ? task.title.trim() : 'Unknown Company';

  const taskDetails = {
    task_id: task.id,
    title: task.title ? task.title.trim() : 'Untitled Task',
    company_name: companyName,
    description: task.description ? task.description.trim() : '',
    project_id: task.project_id,
    project_name: projectData.project_name,
    column_id: task.column_id,
    column_name: task.column_name || 'Unknown Column',
    color_id: task.color_id,
    owner_id: task.owner_id,
    creator_id: task.creator_id,
    date_creation: task.date_creation,
    date_modification: task.date_modification,
    date_due: task.date_due || null,
    priority: task.priority || 0,
    score: task.score || null,
    category_id: task.category_id || null,
    swimlane_id: task.swimlane_id || null,
    tags: task.tags || [],
    is_active: task.is_active,
    status: task.is_active === '1' ? 'Active' : 'Inactive'
  };

  console.log(`📋 Task: "${taskDetails.title}" (Company: ${companyName}, ID: ${task.id})`);
  clientTasks.push(taskDetails);
}

if (clientTasks.length > 0) {
  console.log(`✅ Returning ${clientTasks.length} tasks to check for attachments`);
  return clientTasks.map(task => ({ json: task }));
}

console.log('ℹ️ No tasks found in clients project');
return [{ json: { message: 'No tasks found', project_name: projectData.project_name, task_count: 0 } }];

// Process attachments and prepare for Pinecone without AI embeddings
const attachmentsResponse = $input.first().json;
const taskData = $input.all()[0].json;
const attachments = attachmentsResponse.result || [];

console.log(`Processing ${attachments.length} attachments for task: ${taskData.title}`);

if (attachments.length === 0) {
  console.log(`ℹ️ No attachments found for task: ${taskData.title}`);
  return [];
}

const documentsToIndex = [];

for (const attachment of attachments) {
  // Create a simple hash/vector using basic text processing (no AI needed)
  const content = `Company: ${taskData.company_name}\nTask: ${taskData.title}\nFile: ${attachment.name || 'Unknown File'}\nDescription: ${taskData.description}`;

  // Create a simple vector from text content (character-based approach)
  const simpleVector = Array(1024).fill(0);
  const textForVector = content.toLowerCase();

  // Simple character frequency-based vector generation
  for (let i = 0; i < textForVector.length && i < 1024; i++) {
    const charCode = textForVector.charCodeAt(i);
    simpleVector[i % 1024] = (simpleVector[i % 1024] + charCode / 1000) % 1;
  }

  // Normalize the vector
  const magnitude = Math.sqrt(simpleVector.reduce((sum, val) => sum + val * val, 0));
  const normalizedVector = magnitude > 0 ? simpleVector.map(val => val / magnitude) : simpleVector;

  const documentData = {
    id: `${taskData.company_name.replace(/[^a-zA-Z0-9]/g, '_')}_${attachment.id}`,
    values: normalizedVector,
    metadata: {
      company_name: taskData.company_name,
      task_title: taskData.title,
      task_id: taskData.task_id.toString(),
      file_name: attachment.name || 'Unknown File',
      file_size: attachment.size || 0,
      column_name: taskData.column_name,
      date_creation: taskData.date_creation,
      document_type: 'task_attachment',
      content_preview: content.substring(0, 200)
    }
  };

  console.log(`📎 Prepared attachment: "${attachment.name}" for company "${taskData.company_name}"`);
  documentsToIndex.push(documentData);
}

if (documentsToIndex.length > 0) {
  console.log(`✅ Prepared ${documentsToIndex.length} documents for indexing (no AI needed)`);
  return documentsToIndex.map(doc => ({ json: doc }));
}

return [];
